import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"Emaki Series Documentation","description":"","frontmatter":{"layout":"home","hero":{"name":"Emaki Series","text":"Paper RPG Plugin Suite","tagline":"A Paper 1.21.8+ / Java 25 RPG plugin suite. Install only the modules you need; CoreLib unifies actions, GUI, item sources, PDC data, and presentation rebuilds.","actions":[{"theme":"brand","text":"Getting Started","link":"/en/guide/getting-started"},{"theme":"alt","text":"Architecture","link":"/en/guide/architecture"}]},"features":[{"title":"Check CoreLib first","details":"Every business module depends on CoreLib. Understand item sources, actions, GUI, PDC, expressions, and economy before editing module YAML.","link":"/en/modules/corelib/"},{"title":"Put attributes in PDC","details":"Attribute defines stats, resources, damage types, and conditions. Equipment stats should be written as PDC payloads, not only as lore text.","link":"/en/modules/attribute/"},{"title":"Equipment is layered","details":"Item, Forge, Strengthen, and Gem write separate layers. CoreLib rebuilds the final name, lore, attributes, and display state.","link":"/en/modules/forge/"},{"title":"Read levels, skills, and stations separately","details":"Level manages multi-type progression and exp sources. Skills manages triggers and cooldowns. Cooking manages world stations and result branches.","link":"/en/modules/level/"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":null}'),r={name:"en/index.md"};function n(o,e,d,l,m,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="emaki-series-documentation" tabindex="-1">Emaki Series Documentation <a class="header-anchor" href="#emaki-series-documentation" aria-label="Permalink to &quot;Emaki Series Documentation&quot;">​</a></h1><p>Emaki Series is a set of installable Paper RPG modules. CoreLib provides the shared action, GUI, item-source, PDC, and presentation systems. Business modules add attributes, items, forging, strengthening, gems, levels, skills, cooking stations, codex advancements, and GUI storage.</p><h2 id="who-should-read-this-documentation" tabindex="-1">Who should read this documentation <a class="header-anchor" href="#who-should-read-this-documentation" aria-label="Permalink to &quot;Who should read this documentation&quot;">​</a></h2><ul><li><strong>Server owners and configurators</strong>: installation order, YAML fields, commands, permissions, and troubleshooting.</li><li><strong>Gameplay designers</strong>: equipment growth, materials, strengthening stages, gems, skills, and cooking stations.</li><li><strong>Developers</strong>: CoreLib actions, GUI, item source, PDC, assembly layers, and Attribute APIs.</li><li><strong>Maintainers</strong>: module boundaries, runtime dependencies, and debugging entry points.</li></ul><h2 id="recommended-reading-path" tabindex="-1">Recommended reading path <a class="header-anchor" href="#recommended-reading-path" aria-label="Permalink to &quot;Recommended reading path&quot;">​</a></h2><ol><li>Read <a href="/Emaki_Series/en/guide/introduction.html">Introduction</a> to decide which modules to install.</li><li>Read <a href="/Emaki_Series/en/guide/getting-started.html">Getting Started</a> to build, install, and verify the plugins.</li><li>Before writing YAML, read <a href="/Emaki_Series/en/modules/corelib/">CoreLib</a> for item sources, actions, conditions, expressions, and GUI.</li><li>For equipment progression, read Attribute → Item → Forge / Strengthen / Gem.</li><li>For progression and gameplay systems, read Level, Skills, Cooking, Codex, and Storage separately. They solve different problems.</li></ol><h2 id="module-overview" tabindex="-1">Module overview <a class="header-anchor" href="#module-overview" aria-label="Permalink to &quot;Module overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Role</th><th>Typical use</th></tr></thead><tbody><tr><td><a href="/Emaki_Series/en/modules/corelib/">EmakiCoreLib</a></td><td>Shared foundation</td><td>Start here: actions, GUI, item sources, PDC, expressions, economy, structured presentation.</td></tr><tr><td><a href="/Emaki_Series/en/modules/attribute/">EmakiAttribute</a></td><td>Attribute and combat</td><td>Define stats, resources, damage types, conditions, and public attribute APIs.</td></tr><tr><td><a href="/Emaki_Series/en/modules/item/">EmakiItem</a></td><td>Custom items</td><td>Generate stable item IDs, base attributes, skills, sets, and triggers.</td></tr><tr><td><a href="/Emaki_Series/en/modules/forge/">EmakiForge</a></td><td>Forging</td><td>Use blueprints and materials to modify equipment or create new results.</td></tr><tr><td><a href="/Emaki_Series/en/modules/strengthen/">EmakiStrengthen</a></td><td>Strengthening</td><td>Handle star upgrades, success rates, materials, failure penalties, and protection.</td></tr><tr><td><a href="/Emaki_Series/en/modules/gem/">EmakiGem</a></td><td>Gems</td><td>Manage sockets, opening, inlay, extraction, upgrades, and resonance.</td></tr><tr><td><a href="/Emaki_Series/en/modules/level/">EmakiLevel</a></td><td>Level progression</td><td>Manage multiple level types, exp sources, requirements, PDC, placeholders, and MythicMobs exp drops.</td></tr><tr><td><a href="/Emaki_Series/en/modules/skills/">EmakiSkills</a></td><td>Skills</td><td>Manage active/passive triggers, cooldowns, resource costs, and MythicMobs execution.</td></tr><tr><td><a href="/Emaki_Series/en/modules/cooking/">EmakiCooking</a></td><td>Cooking stations</td><td>Manage chopping board, wok, grinder, steamer, oven, juicer, and fermentation barrel.</td></tr><tr><td><a href="/Emaki_Series/en/modules/codex/">EmakiCodex</a></td><td>Codex and advancements</td><td>Define vanilla advancement pages and nodes in YAML, granted by commands, CoreLib actions, the public API, or event triggers.</td></tr><tr><td><a href="/Emaki_Series/en/modules/storage/">EmakiStorage</a></td><td>GUI storage</td><td>Hold <code>long</code>-scale amounts per slot while preserving the original item, with capacity from config, permissions, command grants, and paid expansion, plus search and sorting.</td></tr></tbody></table>',8)])])}const h=t(r,[["render",n]]);export{g as __pageData,h as default};
